mapper.select:
SELECT p.PRFL_ID, p.CP_ID, p.CS_ID, p.EVSE_ID, p.STACK_LVL,
       p.PRPS, p.KIND, p.RCRNC_KIND, p.VALID_FROM, p.VALID_TO,
       p.RC_ID, p.CS_STATUS,
       p.REG_DT, p.REG_ID, p.UPD_DT, p.UPD_ID
  FROM TB_CHPF001 p


   AND p.CP_ID = #{cond.cpId}


   AND p.CS_ID = #{cond.csId}


   AND p.EVSE_ID = #{cond.evseId}


   AND p.PRPS = #{cond.purpose}


 ORDER BY p.PRFL_ID DESC
 LIMIT #{cond.pageItemSize} OFFSET #{cond.start}

SELECT COUNT(*)
  FROM TB_CHPF001 p


   AND p.CP_ID = #{cond.cpId}


   AND p.CS_ID = #{cond.csId}


   AND p.EVSE_ID = #{cond.evseId}


   AND p.PRPS = #{cond.purpose}

mapper.update:
UPDATE TB_CHPF002
   SET SCHD_LIST_JSON = #{p.scheduleListJson}
 WHERE PRFL_ID = #{p.profileId}

mapper.delete:
DELETE FROM TB_CHPF001
 WHERE PRFL_ID = #{profileId}
   AND CP_ID   = #{cpId}
   AND CS_ID   = #{csId}
